import{_ as a,o as e,c as d,a2 as r}from"./chunks/framework.z3u3TMv0.js";const u=JSON.parse('{"title":"문제 해결 대조표","description":"MiniTavern ↔ Ollama/LM Studio 연결 실패, 타임아웃, CORS, 방화벽 등 흔한 문제와 처리.","frontmatter":{"title":"문제 해결 대조표","description":"MiniTavern ↔ Ollama/LM Studio 연결 실패, 타임아웃, CORS, 방화벽 등 흔한 문제와 처리.","head":[["meta",{"name":"keywords","content":"주점,AI 주점,MiniTavern,AI 파트너,AI 친구,AI 로컬 채팅,Silly Tavern,SillyTavern,모바일 Silly Tavern,Silly Tavern 모바일,Silly Tavern 안드로이드,Silly Tavern iOS,AI 롤플레이,캐릭터 카드,AI 채팅,모바일 AI,오프라인 AI,AI 스토리,로컬 LLM,Ollama,LM Studio,세계관,정규식,BYOK,사용자 가이드,매뉴얼"}],["meta",{"property":"og:title","content":"문제 해결 대조표 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern ↔ Ollama/LM Studio 연결 실패, 타임아웃, CORS, 방화벽 등 흔한 문제와 처리."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/ko/troubleshoot"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/ko/troubleshoot"}]]},"headers":[],"relativePath":"ko/troubleshoot.md","filePath":"ko/troubleshoot.md","lastUpdated":1787224147000}'),o={name:"ko/troubleshoot.md"};function l(i,t,h,n,s,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="문제-해결-대조표" tabindex="-1">문제 해결 대조표 <a class="header-anchor" href="#문제-해결-대조표" aria-label="Permalink to &quot;문제 해결 대조표&quot;">​</a></h1><p>현상별로 찾으세요. 안 되면 App <strong>설정 → 도움말과 피드백 → 문제 제보</strong>（스크린샷·문제 로그）또는 <strong>피드백 이메일</strong>. 가능하면: OS, 도구（Ollama / LM Studio / KoboldCPP 등）, Base URL（IP 뒤 두 구간 마스킹）, 오류 원문.</p><h2 id="연결-테스트" tabindex="-1">연결 / 테스트 <a class="header-anchor" href="#연결-테스트" aria-label="Permalink to &quot;연결 / 테스트&quot;">​</a></h2><table tabindex="0"><thead><tr><th>현상</th><th>가능 원인</th><th>처리</th></tr></thead><tbody><tr><td>연결 타임아웃</td><td>다른 Wi‑Fi, 방화벽, 서비스가 <code>0.0.0.0</code> 미리슨</td><td>같은 망; 포트 개방; 각 도구 「서비스 / LAN」장</td></tr><tr><td>즉시 실패 / 연결 불가</td><td>IP·포트 오류, 서비스 미기동</td><td>PC 브라우저 <code>http://IP:포트/v1/models</code>; Base URL 확인</td></tr><tr><td>localhost여도 실패</td><td>폰의 localhost는 폰 자신</td><td>PC LAN IP로 변경</td></tr><tr><td>401 / 키 오류</td><td>일부 로컬 스택이 Key 검증</td><td>비어 있지 않은 자리, 또는 도구 문서대로 인증 끔</td></tr><tr><td>404 / 모델 없음</td><td>로컬과 모델명 불일치</td><td><code>ollama list</code> 또는 <code>/v1/models</code>에서 <strong>전체 id</strong></td></tr><tr><td>응답 있으나 채팅 빈칸/오류</td><td>호환성, 타임아웃 짧음, 미로드</td><td>타임아웃↑; 모델 load 확인; 작은 모델로 경로 검증</td></tr></tbody></table><h2 id="네트워크와-시스템" tabindex="-1">네트워크와 시스템 <a class="header-anchor" href="#네트워크와-시스템" aria-label="Permalink to &quot;네트워크와 시스템&quot;">​</a></h2><table tabindex="0"><thead><tr><th>현상</th><th>가능 원인</th><th>처리</th></tr></thead><tbody><tr><td>PC OK, 폰 안 됨</td><td>게스트 Wi‑Fi 격리, AP 격리</td><td>주 네트워크; 임시로 폰 핫스팟에 PC 접속</td></tr><tr><td>간헐 끊김</td><td>PC 절전, IP 변경</td><td>절전 금지; IP 재확인·연결 갱신</td></tr><tr><td>VPN 후 이상</td><td>분기/가상 NIC</td><td>테스트 시 VPN 끄거나 LAN 제외</td></tr></tbody></table><h2 id="url-표기" tabindex="-1">URL 표기 <a class="header-anchor" href="#url-표기" aria-label="Permalink to &quot;URL 표기&quot;">​</a></h2><table tabindex="0"><thead><tr><th>올바른 예</th><th>잘못된 예</th></tr></thead><tbody><tr><td><code>http://192.168.1.8:11434/v1</code></td><td><code>http://localhost:11434/v1</code></td></tr><tr><td><code>http://192.168.1.8:1234/v1</code></td><td><code>http://192.168.1.8:1234/v1/chat/completions</code></td></tr><tr><td><code>http://192.168.1.8:5001/v1</code></td><td><code>https://192.168.1.8:11434/v1</code>（로컬에 인증서 없으면 https 강제 금지）</td></tr><tr><td><code>http://192.168.1.8:8080/v1</code></td><td></td></tr></tbody></table><h2 id="http-평문" tabindex="-1">HTTP 평문 <a class="header-anchor" href="#http-평문" aria-label="Permalink to &quot;HTTP 평문&quot;">​</a></h2><p>MiniTavern <strong>Android</strong>는 평문 HTTP（LAN 흔함）허용. 여전히 막히면:</p><ul><li>Base URL이 <code>http://</code>인지</li><li>시스템/제조사 네트워크 보호가 LAN을 막지 않는지</li><li>iOS ATS 제한 시 문서의 LAN 주소 우선; 실패 시 OS 버전·오류 제보</li></ul><h2 id="cors" tabindex="-1">CORS <a class="header-anchor" href="#cors" aria-label="Permalink to &quot;CORS&quot;">​</a></h2><p>브라우저 웹페이지만 CORS에 자주 걸림; <strong>네이티브 App 직결 API는 보통 CORS 무관</strong>. PC 브라우저 프론트가 실패해도 MiniTavern 실패는 아님 — App 내 테스트 기준.</p><h2 id="성능" tabindex="-1">성능 <a class="header-anchor" href="#성능" aria-label="Permalink to &quot;성능&quot;">​</a></h2><table tabindex="0"><thead><tr><th>현상</th><th>처리</th></tr></thead><tbody><tr><td>첫 글자 매우 느림</td><td>더 작은 양자화/파라미터; GPU 사용 확인</td></tr><tr><td>생성 중 멈춤</td><td>타임아웃↑; 다른 VRAM 점유 끔; PC 로그 OOM</td></tr></tbody></table><h2 id="관련-링크" tabindex="-1">관련 링크 <a class="header-anchor" href="#관련-링크" aria-label="Permalink to &quot;관련 링크&quot;">​</a></h2><ul><li><a href="./manual/errors">매뉴얼 · 오류 코드</a>（테스트 / 채팅 API）</li><li><a href="./quickstart">30분 퀵스타트</a></li><li><a href="./local/tools">도구 개요</a> · <a href="./local/models">추천 모델</a></li><li><a href="./ollama/lan">Ollama LAN</a></li><li><a href="./lmstudio/server">LM Studio Local Server</a></li><li><a href="./koboldcpp/server">KoboldCPP API</a></li><li><a href="./llamacpp/server">llama.cpp server</a></li><li><a href="./connect-app/minitavern">MiniTavern 설정</a></li></ul>',17)])])}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
